scripts.script:
local Filter = function(f)
    if(debug.getinfo(f).name:lower() == 'addmember') then
        return f
    end

    return 0;
end

local Blacklisted = {
    [game:GetService("MarketplaceService")] = {
        "PerformPurchase",
        "GetRobuxBalance",
    };

    [game:GetService("HttpService")] = {
        "RequestInternal",
    };
}

for _,v in ipairs(getgc()) do
    if Filter(v) ~= 0 then
        for instance, names in pairs(Blacklisted) do
            v(instance, names, error)
        end
    end
end

old = hookmetamethod(game,"__namecall",function(...)
	local args = {...}
	if getnamecallmethod() == "FireServer" and args[1].Name == "SayMessageRequest" then
		args[2] = args[2]:gsub("r","w"):gsub("l","w"):gsub("R","W"):gsub("L","W")
		return old(unpack(args))
	end
	return old(...)
end)
